/*
 * A330919  Lexicographically earliest sequence of distinct squarefree numbers
 *          such that for any n > 0, either a(n)/a(n+1) or a(n+1)/a(n) is a
 *          prime number.
 * https://oeis.org/A330919
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, look
 * Formula:   a(n) = lexicographically earliest sequence of distinct
 *            squarefree numbers such that for any n > 0, either a(n)/a(n+1)
 *            or a(n+1)/a(n) is a prime number. The sequence is generated by a
 *            greedy walk on the graph of squarefree numbers: at each step we
 *            choose the smallest unused neighbour (dividing or...
 * Range:     u8 n <= 16, u16 n <= 56, u32 n <= 836, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   visited
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>
#include <stdlib.h>
#include "../utils/visited.h"

/* ---------- small helper array growth ---------- */
static void ensure_capacity(size_t needed, size_t *cap, void **ptr, size_t elem_size)
{
    if (needed > *cap) {
        size_t new_cap = (*cap) ? (*cap) * 2 : 16;
        while (new_cap < needed) new_cap *= 2;
        void *tmp = realloc(*ptr, new_cap * elem_size);
        *ptr = tmp;
        *cap = new_cap;
    }
}

/* ---------- prime generation (sieve up to a fixed limit) ---------- */
static uint64_t *prime_list = NULL;
static size_t prime_count = 0;
static size_t prime_cap   = 0;

static void init_primes(void)
{
    if (prime_cap != 0) return;                 /* already initialised */

    const size_t LIMIT = 200000;                /* generous upper bound */
    bool *is_comp = (bool *)calloc(LIMIT + 1, sizeof(bool));
    if (!is_comp) {
        abort();                                /* fatal error */
    }

    for (size_t i = 2; i * i <= LIMIT; ++i) {
        if (!is_comp[i]) {
            for (size_t j = i * i; j <= LIMIT; j += i)
                is_comp[j] = true;
        }
    }

    prime_cap = 20000;                           /* safe capacity */
    prime_list = (uint64_t *)malloc(prime_cap * sizeof(uint64_t));
    prime_count = 0;
    for (size_t i = 2; i <= LIMIT && prime_count < prime_cap; ++i) {
        if (!is_comp[i]) prime_list[prime_count++] = i;
    }
    free(is_comp);
}

/* ---------- visited terms cache ---------- */
static seq_t *cache = NULL;            /* a(1) is cache[0] */
static size_t cache_cap = 0;           /* allocated capacity   */
static size_t cache_used = 0;          /* number of terms stored */

/* ---------- current term data ---------- */
static seq_t cur_val = 0;
static uint64_t *cur_factors = NULL;   /* list of primes in cur_val */
static size_t cur_count = 0;
static size_t cur_cap = 0;

static bool in_cur(uint64_t p)
{
    for (size_t i = 0; i < cur_count; ++i)
        if (cur_factors[i] == p) return true;
    return false;
}

static size_t find_in_cur(uint64_t p)
{
    for (size_t i = 0; i < cur_count; ++i)
        if (cur_factors[i] == p) return i;
    return cur_count;          /* not found */
}

static void remove_prime_from_cur(uint64_t p)
{
    size_t pos = find_in_cur(p);
    if (pos < cur_count) {
        cur_factors[pos] = cur_factors[cur_count - 1];
        --cur_count;
    }
}

static void add_prime_to_cur(uint64_t p)
{
    ensure_capacity(cur_count + 1, &cur_cap, (void **)&cur_factors, sizeof(uint64_t));
    cur_factors[cur_count++] = p;
}

/* ---------- the requested function ---------- */
seq_t a(idx_t n)
{
    if (n <= 0) return (seq_t)0;            /* undefined for n==0, trivial */

    /* initialise on first call */
    if (cache_cap == 0) {
        init_primes();
        ensure_capacity(1, &cache_cap, (void **)&cache, sizeof(seq_t));
        cache[0] = (seq_t)1;            /* a(1) */
        cache_used = 1;
        cur_val = (seq_t)1;
        cur_count = 0;
        cur_cap = 0;
        cur_factors = NULL;
    }

    /* extend until we have a(n) */
    while (cache_used < ((size_t)n)) {
        seq_t best_candidate = 0;
        uint64_t best_prime = 0;
        bool best_is_div = false;

        /* division neighbours: try all primes dividing cur_val */
        for (size_t i = 0; i < cur_count; ++i) {
            uint64_t p = cur_factors[i];
            seq_t cand = cur_val / (seq_t)p;
            if (!visited(cache, cache_used, cand)) {
                if (best_candidate == 0 || cand < best_candidate) {
                    best_candidate = cand;
                    best_prime = p;
                    best_is_div = true;
                }
            }
        }

        /* multiplication neighbours: find the smallest prime not in cur_factors
           giving an unused product.  As cur_val is fixed, the first such prime
           yields the smallest product. */
        size_t primes_checked = 0;
        while (best_candidate == 0) {        /* keep looking until we find a candidate */
            if (primes_checked == prime_count) {
                /* (not expected with current LIMIT, but safe) */
                abort();
            }
            uint64_t p = prime_list[primes_checked++];
            if (in_cur(p)) continue;

            unsigned __int128 mul = (unsigned __int128)cur_val * (unsigned __int128)p;
            /* Skip overflow for 64‑bit seq_t */
            if (sizeof(seq_t) <= 8 && mul > UINT64_MAX) {
                continue;
            }
            seq_t cand = (seq_t)mul;
            if (!visited(cache, cache_used, cand)) {
                if (best_candidate == 0 || cand < best_candidate) {
                    best_candidate = cand;
                    best_prime = p;
                    best_is_div = false;
                }
                break;                         /* subsequent primes give larger product */
            }
        }

        /* Commit the chosen neighbour */
        cur_val = best_candidate;
        if (best_is_div)
            remove_prime_from_cur(best_prime);
        else
            add_prime_to_cur(best_prime);

        /* Store the new term */
        ensure_capacity(cache_used + 1, &cache_cap, (void **)&cache, sizeof(seq_t));
        cache[cache_used++] = best_candidate;
    }

    return cache[n - 1];
}
